"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6728],{566(e){e.exports=JSON.parse('{"title":"2024\ub144, \ud504\ub860\ud2b8\uc5d4\ub4dc","date":"2024-11-07","coverUrl":null,"html":"<h2 data-notion-block-id=\\"134e548d-8a8e-800e-bd6f-dc7aaff933a8\\" id=\\"134e548d-8a8e-800e-bd6f-dc7aaff933a8\\">2024\ub144, \ud504\ub860\ud2b8\uc5d4\ub4dc</h2><a href=\\"https://tsh.io/state-of-frontend/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tsh.io/state-of-frontend/</a><p data-notion-block-id=\\"134e548d-8a8e-80ce-bce1-dec95a9499de\\"><b>\uc2ec\uc724\uc12d</b>: \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \ud1b5\uacc4\ub97c \ubc14\ud0d5\uc73c\ub85c \ub3d9\ud5a5\uacfc \uad00\uc810\uc744 \uc5bb\uc744 \uc218 \uc788\ub294 \uc790\ub8cc\uc785\ub2c8\ub2e4. \uc804\ub9dd\uc744 \uc608\uce21\ud558\ub294 \uac83\uc740 \ubd88\uac00\ub2a5\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub3d9\ud5a5\uacfc \uad00\uc810\ub4e4\uc740 \uc81c\ud488\uc5d0 \ubd80\uc871\ud55c \uac83\uc774 \ubb34\uc5c7\uc778\uc9c0\ub97c \ub2e4\uc2dc \uc0dd\uac01\ud574\ubcf4\ub294 \uacc4\uae30\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b8\ub80c\ub4dc\uc5d0 \ub530\ub77c\uac00\uc9c0 \uc54a\ub294 \uc790\uc2e0\ub9cc\uc758, \uc81c\ud488\ub9cc\uc758 \uc6d0\uce59\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \uc88b\uc740 \uad00\uc810\uc778 \ubd80\ubd84\uc740 \ucc44\ud0dd\ud574\uc57c\uaca0\uc8e0.</p><p data-notion-block-id=\\"fa8ce4f2-2818-47a5-ba07-ce5a731cdc55\\"><b>\uae40\ub300\uad00</b>: \ud504\ub860\ud2b8\uc5d4\ub4dc \ud1b5\uacc4\ub97c \ubcf4\uba70, \uc5ec\uc804\ud55c React\uc758 \uc2dc\uc7a5 \uc810\uc720\uc728\ub3c4 \uc54c \uc218 \uc788\uc5c8\uace0, \uc774\uc678\uc758 Vue \uc0ac\uc6a9\ub960\ub3c4 \ubcf4\uba74 \ubcf8\uc778\uc758 \uc0c1\ud669\uc5d0 \ub9de\ub294 \uae30\uc220 \uc120\ud0dd\uc774 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc720\uba85\ud55c \uae30\uc5c5\uc5d0\uc11c \ub0b4\ub294 \uc2e0\uae30\uc220\uc774\ub77c\uace0 \ubb34\uc791\uc815 \ucc44\ud0dd\ud558\ub294 \uac83\uc774 \uc544\ub2cc \uc548\uc815\uc801\uc778 \ubc29\ud5a5\uc73c\ub85c \uae30\uc220\uc744 \uc120\ud0dd\ud558\ub294 \ud750\ub984\ub3c4 \uc778\uc0c1\uc801\uc774\uc9c0\ub9cc, \uc5b8\uc81c \ud504\ub860\ud2b8\uc5d4\ub4dc \uc2dc\uc7a5\uc774 \uaca9\ubcc0\ud560\uc9c0\ub294 \uc544\ubb34\ub3c4 \ubaa8\ub97c\uac83\uc774\ub2c8 \uae30\uc220\uc758 \ubcc0\ud654\ub97c \uc5b8\uc81c\ub098 \uc8fc\uc2dc\ud574\uc57c\ud560 \uac81\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"134e548d-8a8e-80e0-b889-e9780f07d52a\\" id=\\"134e548d-8a8e-80e0-b889-e9780f07d52a\\">\ub9c8\uc774\ud06c\ub85c \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \uc0c8\ub85c\uc6b4 \uc811\uadfc</h2><a href=\\"https://blog.cloudflare.com/fragment-piercing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/fragment-piercing/</a><p data-notion-block-id=\\"134e548d-8a8e-803e-9b9a-c9a1e1d68391\\"><b>\uc2ec\uc724\uc12d</b>: Cloudflare\uc5d0\uc11c Fragment Piercing\uc774\ub77c\ub294 \uc811\uadfc \ubc29\ubc95\uc73c\ub85c \ub9c8\uc774\ud06c\ub85c \ud504\ub860\ud2b8\uc5d4\ub4dc\ub97c \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uac1c\ub150\uacfc \uae30\uc874\uc758 \uc5ec\ub7ec\uac00\uc9c0 \uc811\uadfc\ubc29\uc2dd\uc744 \ubcf4\uc2dc\ub824\uba74 <a href=\\"https://martinfowler.com/articles/micro-frontends.html\\">\ub9c8\ud2f4 \ud30c\uc6b8\ub7ec\uc758 \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694. Fragment Piercing\uc740 JS\uc744 \ud1b5\ud574 \ub7f0\ud0c0\uc784\uc5d0\uc11c \ud1b5\ud569\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c <a href=\\"https://module-federation.io/\\">Module Federation</a>\uacfc \uac19\uc9c0\ub9cc, gateway worker(\uc11c\ubc84\ub9ac\uc2a4 \ud568\uc218)\ub97c \ud1b5\ud574 \ube60\ub974\uac8c \ub85c\ub4dc\ud558\uace0, \uc810\uc9c4\uc801 \ub3c4\uc785\uc774 \uac00\ub2a5\ud55c \uac83\uc5d0 \uae30\uc220\uc5d0 \uc8fc\ubaa9\ud558\uace0 \uc788\uc744\ub9cc \ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"132e548d-8a8e-8016-859c-d19cc51c08f6\\" id=\\"132e548d-8a8e-8016-859c-d19cc51c08f6\\">\ud234\ud301\uc740 \uc5b8\uc81c \uc368\uc57c \ud558\ub294\uac00</h2><a href=\\"https://css-tricks.com/tooltip-best-practices/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/tooltip-best-practices/</a><p data-notion-block-id=\\"134e548d-8a8e-80c9-8928-f9da957546c5\\">\ud234\ud301\uc774 \uc9c0\ud5a5\ud574\uc57c \ud558\ub294 \uc810, \uc9c0\uc591\ud574\uc57c \ud558\ub294 \uc810\uc744 \uc815\uc758\uc640 \ub2e4\ub978 \uae30\uc0ac\ub97c \ud1b5\ud574\uc11c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. popover \uad00\ub828 UI \ud328\ud134\ub4e4\uc740 \uc6a9\ub3c4\uc5d0 \ub9de\uac8c \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0c1\uae30\uc2dc\ucf1c\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"134e548d-8a8e-8088-9fb2-c670be8d6bab\\" id=\\"134e548d-8a8e-8088-9fb2-c670be8d6bab\\">Core Web Vital \uc810\uc218 \uc62c\ub9ac\uae30(2024\ub144)</h2><a href=\\"https://web.dev/articles/top-cwv\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/articles/top-cwv</a><p data-notion-block-id=\\"134e548d-8a8e-80f3-a835-c663392acfaf\\">Core Web Vital \uc810\uc218\ub97c \uc62c\ub9ac\ub294 \ubc29\ubc95\uc740 \ud06c\uac8c \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\uc558\uc9c0\ub9cc, bfcache\uc5d0 \ub300\ud55c \uc124\uba85, \uadf8\ub9ac\uace0 INP\ub85c\uc758 \ubcc0\uacbd\uc810\uc740 \ubcfc\ub9cc\ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"134e548d-8a8e-800d-affc-eb8869c2f8ad\\" id=\\"134e548d-8a8e-800d-affc-eb8869c2f8ad\\">\uc5ec\ub7ec\uac00\uc9c0 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://preactjs.com/blog/simplifying-islands-arch/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://preactjs.com/blog/simplifying-islands-arch/</a><a href=\\"https://reactiive.io/articles/animated-spiral\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactiive.io/articles/animated-spiral</a><a href=\\"https://www.atomwolf.org/posts/rendering-outlines-with-a-post-processing-shader/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.atomwolf.org/posts/rendering-outlines-with-a-post-processing-shader/</a><a href=\\"https://mozzius.dev/post/3l777nhz4h32w\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mozzius.dev/post/3l777nhz4h32w</a><a href=\\"https://robinmalfait.com/blog/conditional-react-hooks-pattern\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://robinmalfait.com/blog/conditional-react-hooks-pattern</a><p data-notion-block-id=\\"134e548d-8a8e-8093-a3c8-dfe5adfe9450\\">\uccab\ubc88\uc9f8 \uae00\uc740 React Native Skia\ub97c \ud1b5\ud574\uc11c \uba4b\uc9c4 \uc560\ub2c8\uba54\uc774\uc158\uc744 \uad6c\ud604\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 React Three Fiber\uc744 \uae30\ubc18\uc73c\ub85c \uc170\uc774\ub354\ub97c \ucd94\uac00\ud558\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc774\uc9c0\ub9cc, \ub9e8 \ubc11\uc5d0 \uac01\uc885 \ucc38\uace0\ud55c \uc790\ub8cc\uac00 \ub2e4\uc591\ud558\uace0 \uacf5\ubd80\ud558\ub294\ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uc5ec \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc138\ubc88\uc9f8\ub294 React Native\uc5d0\uc11c \ub124\uc774\ud2f0\ube0c \ub290\ub08c\uc774 \ub098\ub3c4\ub85d \ud558\uae30 \uc704\ud574 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \uc9da\uc5b4\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub124\ubc88\uc9f8 \uae00\uc740 React\uc758 \ud6c5 \uc548\uc5d0\uc11c \uc870\uac74\ubd80 \ub85c\uc9c1\uc744 \uc0bd\uc785\ud558\ub294 \ubc29\ubc95\uc744 \uad6c\ud604\ud558\ub294 \uc774\uc720, \uad6c\ud604 \ubc29\ubc95\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \uae00\uc740 Island Architecture\ub97c \uc18c\uac1c\ud558\uace0 Preact \uae30\ubc18\uc73c\ub85c \uc5b4\ub5bb\uac8c \uad6c\ud604\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. Island Architecture\uac00 \uad81\uae08\ud558\uc2dc\uba74 <a href=\\"https://www.patterns.dev/vanilla/islands-architecture/\\">patterns.dev\uc758 \uc18c\uac1c\uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><p data-notion-block-id=\\"134e548d-8a8e-8017-8f40-fc39b71c4a02\\"></p>"}')}}]);